-- geostats-v16.2.6-priority-150-legacy-reaudit
-- First-principles review of the highest-priority generic non-FAOSTAT legacy rejections.
-- Clearing a legacy block does NOT make a category playable; all source, integrity, duplication, editorial and activation gates still apply.
begin;

alter table public.legacy_category_rejections_v16_2_6 drop constraint if exists legacy_category_rejections_v16_2_6_default_decision_check;
alter table public.legacy_category_rejections_v16_2_6 add constraint legacy_category_rejections_v16_2_6_default_decision_check check(default_decision in ('requires_reaudit','cleared_for_reconsideration','confirmed_exclusion'));

create table if not exists public.legacy_rejection_first_principles_reaudit_v16_2_6 (
  legacy_key text primary key references public.legacy_category_rejections_v16_2_6(legacy_key) on delete cascade,
  source_line integer not null unique,
  category_title text not null,
  legacy_source text not null,
  legacy_domain_series text,
  historical_integrity_status text,
  historical_quality text,
  editorial_disposition text not null check(editorial_disposition in ('advance_to_validation','clear_legacy_block_current_path_governs','hold_for_family_curation','retain_exclusion')),
  legacy_guard_action text not null check(legacy_guard_action in ('clear_generic_legacy_block','keep_reaudit_block','confirm_reasoned_exclusion')),
  reason_class text not null,
  first_principles_rationale text not null,
  recommended_next_action text not null,
  linked_tracker_ids text,
  linked_tracker_dispositions text,
  reviewed_at timestamptz not null default now()
);
alter table public.legacy_rejection_first_principles_reaudit_v16_2_6 enable row level security;
revoke all on public.legacy_rejection_first_principles_reaudit_v16_2_6 from public,anon,authenticated;
grant select,insert,update,delete on public.legacy_rejection_first_principles_reaudit_v16_2_6 to service_role;


on conflict(legacy_key) do update set
  source_line=excluded.source_line,
  category_title=excluded.category_title,
  legacy_source=excluded.legacy_source,
  legacy_domain_series=excluded.legacy_domain_series,
  historical_integrity_status=excluded.historical_integrity_status,
  historical_quality=excluded.historical_quality,
  editorial_disposition=excluded.editorial_disposition,
  legacy_guard_action=excluded.legacy_guard_action,
  reason_class=excluded.reason_class,
  first_principles_rationale=excluded.first_principles_rationale,
  recommended_next_action=excluded.recommended_next_action,
  linked_tracker_ids=excluded.linked_tracker_ids,
  linked_tracker_dispositions=excluded.linked_tracker_dispositions,
  reviewed_at=now();

update public.legacy_category_rejections_v16_2_6 r
set default_decision = case a.legacy_guard_action
      when 'clear_generic_legacy_block' then 'cleared_for_reconsideration'
      when 'confirm_reasoned_exclusion' then 'confirmed_exclusion'
      else 'requires_reaudit'
    end,
    required_action = a.recommended_next_action
from public.legacy_rejection_first_principles_reaudit_v16_2_6 a
where a.legacy_key=r.legacy_key;

update public.legacy_rejection_semantic_aliases_v16_2_6 s
set review_status = case a.legacy_guard_action
      when 'clear_generic_legacy_block' then 'cleared'
      when 'confirm_reasoned_exclusion' then 'confirmed_exclusion'
      else 'requires_reaudit'
    end,
    rationale = concat(s.rationale, ' | Priority-150 first-principles review: ', a.first_principles_rationale)
from public.legacy_rejection_first_principles_reaudit_v16_2_6 a
where a.legacy_key=s.legacy_key;

alter table public.tracker_legacy_rejection_collisions_v16_2_6 add column if not exists reaudit_disposition text;
alter table public.tracker_legacy_rejection_collisions_v16_2_6 add column if not exists reaudit_guard_action text;

update public.tracker_legacy_rejection_collisions_v16_2_6 c
set reaudit_disposition=a.editorial_disposition,
    reaudit_guard_action=a.legacy_guard_action
from public.legacy_rejection_first_principles_reaudit_v16_2_6 a
where a.source_line=c.legacy_source_line;

-- Fail-safe: a "cleared" legacy decision is only removal of the historical veto.
-- The runtime view continues to require editorial approval, strict quality pass,
-- no hard source/integrity blocker, and no remaining legacy blocker.
commit;
